-- Alubri's six intimate-care products (Vaginal Moisturizing Gel, Intimate
-- Serum, Calming Cream, Vulva Balm, Vaginal Wellness Kit, Rejuvenate &
-- Restore Kit), rebuilt 2026-09-29 using alubri.com as the only source.
-- Catalog entries only — Alubri is NOT an ayna brand partner. Extracted
-- from a regenerated supabase/seed/product_catalog.sql
-- (`npm run catalog:export`); just the 6 Alubri rows, safe to run
-- standalone. Idempotent: safe to re-run (updates the 5 existing rows in
-- place, inserts the new Rejuvenate & Restore Kit).

insert into public.product_catalog (id, name, brand, category, product_type, summary, price, image, url, tags, health_functions, where_to_buy, where_to_buy_in_stock, safety, doctor_opinion, community_review, effectiveness, clinician_opinion_source, clinician_attribution, source, internal, requires_prescription, user_rating, is_active, extra)
values
  ('p-alubri-vaginal-moisturizing-gel', 'Alubri Vaginal Moisturizing Gel', 'Alubri', 'intimate-care', 'physical', 'A hormone-free, fragrance-free internal vaginal moisturizer that Alubri says delivers up to 72 hours of hydration from one application. It pairs hyaluronic acid (sodium hyaluronate) and lactic acid with Alubri''s proprietary "Activated Oil Complex" (pre-activated coconut and rosehip oils), which the brand says balances the vaginal microbiome. Each box is a 50 mL tube with 8 single-use applicators; used twice a week, one box lasts about 4 weeks.', '$29.99 (50 mL, 8 applicators)', '/products/alubri/vaginal-moisturizing-gel.webp', 'https://alubri.com/products/vaginal-moisturizing-gel', '["discomfort","comfort","menopause","hormone-free"]'::jsonb, '["vaginal-health"]'::jsonb, '["alubri.com","Amazon","Walmart","Target","Grove"]'::jsonb, '{}'::jsonb, '{"fdaStatus":"alubri.com presents it as a hormone-free personal-care moisturizer and does not describe it as an FDA-cleared device or drug.","materials":"50 mL (1.7 fl oz) tube with 8 single-use applicators. Ingredients: aqua (water), glucomannan, hydrolyzed Rosa canina (rosehip) fruit oil, hydrolyzed Cocos nucifera (coconut) oil, sodium hyaluronate, lactic acid, Hylocereus undatus (dragon fruit) fruit extract, Aloe barbadensis leaf juice, propanediol, xanthan gum, potassium sorbate, sodium benzoate, benzyl alcohol, benzoic acid. Fragrance-free and hormone-free.","recalls":"No recalls are mentioned on alubri.com; check current regulator and manufacturer recall notices.","sideEffects":"Alubri says some women feel a mild warming or blushing sensation on first use, or brief stinging from the lactic acid, that usually fades within minutes. If discomfort persists, stop and see a doctor. Full warnings are listed below.","opinionAlerts":"The clinical figures (72-hour hydration, microbiome changes) come from a study Alubri describes on its own site; the full study isn''t published there."}'::jsonb, 'Alubri says the gel was developed by Dr. Nicole Kerner, its co-founder and Chief Medical Officer, a board-certified, menopause-certified OB-GYN with more than 20 years in women''s health.

The brand cites an independent, third-party, IRB-approved study run under ISO Good Laboratory Practices: 51 symptomatic menopausal women used the gel twice a week for one month. Brand-reported results: one application raised vaginal hydration by 64% at 72 hours, and 94% said their vagina felt moisturized, 94% hydrated, and 92% soothed.

Alubri also reports that a single application measurably increased Lactobacillus (the "good" vaginal bacteria) and decreased Gardnerella vaginalis, with the changes sustained over four weeks. These are brand-reported results; the full study isn''t published on alubri.com.', 'Customer reviews for this gel are on its Amazon listing, and a Reddit r/AskONLYWomenOver30 thread has women comparing the vaginal moisturizers they''ve tried (both linked below). Neither site allows automated access, so ayna hasn''t pulled a rating or quotes from them; read them directly. alubri.com itself shows no star rating, only the brand''s own study results: 94% of participants said the fragrance-free gel smells good and 88% said it stayed put.', 'Alubri reports a 64% increase in vaginal hydration 72 hours after one application, plus favorable microbiome changes, in its own study of 51 menopausal women. No independent study of this product is cited on alubri.com.', 'brand', 'Sourced only from Alubri''s own site (alubri.com), not independent clinical literature.', 'curated', true, false, null, true, '{"faqUrl":"https://alubri.com/pages/faq","doctorOpinionShort":"Alubri cites a third-party study of 51 menopausal women: one application raised vaginal hydration 64% at 72 hours, and 94% said they felt moisturized. Developed by a menopause-certified OB-GYN. Brand-reported results.","doctorOpinionCitations":[{"url":"https://alubri.com/products/vaginal-moisturizing-gel","label":"alubri.com: where Alubri presents these results"},{"url":"https://alubri.com/pages/science","label":"alubri.com: Science (microbiome results)"}],"whoItsFor":["Vaginal dryness from perimenopause, menopause, or postmenopause","Hormone-related dryness from surgical menopause, breastfeeding, or certain medications (including aromatase inhibitors and anti-estrogen therapies)","Women who want a hormone-free option, including those with a history of estrogen-receptor-positive breast cancer","Anyone looking to support vaginal microbiome balance"],"howToUse":{"intro":"Per Alubri''s own directions:","steps":["Attach a single-use applicator to the tube and squeeze to fill to 3 grams.","Insert the applicator into the vagina and push to release the gel.","Remove the applicator and throw it away.","Use twice a week, ideally at bedtime, or as needed. For best absorption, lie flat for about 10 minutes afterward.","Using it during the day? Wait at least 10 minutes before swimming or bathing.","Also using vaginal estrogen? Alubri suggests using the gel on alternate nights (for example, estrogen Monday and Thursday, gel Tuesday and Friday)."],"sourceUrl":"https://alubri.com/products/vaginal-moisturizing-gel","sourceLabel":"alubri.com: Vaginal Moisturizing Gel"},"warnings":["A mild warming or blushing feeling on first use is normal per Alubri. If discomfort persists, stop and see a doctor.","Alubri says a slight increase in discharge is normal at first and should ease within a few uses.","Itching or irritation that persists despite a moisturizer can be a sign of infection. See a doctor.","Not tested for compatibility with condoms, per Alubri."],"ingredients":"Sodium hyaluronate (hyaluronic acid), lactic acid, Activated Oil Complex (hydrolyzed coconut and rosehip oils), dragon fruit extract, aloe, glucomannan.","ingredientScienceNote":"These are the key ingredients Alubri highlights on its site, not the full ingredient list. The complete list is under Materials on the Evidence view.","ingredientScience":[{"name":"Coconut and rosehip oils (Activated Oil Complex)","text":"Applied to dry skin twice a day for 2 weeks, virgin coconut oil improved hydration as well as mineral oil in a randomized, double-blind trial. An NIH-indexed review notes rosehip oil is rich in linoleic acid and antioxidants that may help calm skin inflammation. These studies used ordinary oils on skin, not Alubri''s \"pre-activated\" blend, so the brand''s microbiome claims aren''t tested by them.","citations":[{"url":"https://pubmed.ncbi.nlm.nih.gov/15724344/","label":"PubMed (NIH): Virgin coconut oil vs. mineral oil for dry skin, randomized trial (Dermatitis, 2004)"},{"url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC5796020/","label":"NIH (PMC): Anti-inflammatory and skin barrier effects of plant oils, incl. rosehip (Int J Mol Sci, 2017)"}]},{"name":"Lactic acid","text":"In a healthy vagina dominated by Lactobacillus, those bacteria make lactic acid, which keeps pH low (about 3.5 on average in one NIH-indexed study) and may help protect against infection. A 2021 systematic review found there isn''t yet high-quality evidence that lactic acid products cure bacterial vaginosis or shift the vaginal microbiome, so they''re best seen as pH support.","citations":[{"url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC3819307/","label":"NIH (PMC): Vaginal pH and lactic acid when lactobacilli dominate (PLoS One, 2013)"},{"url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC7877752/","label":"NIH (PMC): Lactic acid products for bacterial vaginosis, systematic review (PLoS One, 2021)"}]},{"name":"Sodium hyaluronate (hyaluronic acid)","text":"Hyaluronic acid holds water in tissue. In a randomized trial of 144 postmenopausal women with vaginal dryness, a hyaluronic acid vaginal gel used every 3 days for 30 days improved dryness symptoms in 84% of women, about the same as estriol (estrogen) cream at 89%. That trial tested a different gel, so it supports the ingredient, not Alubri''s product specifically.","citations":[{"url":"https://pubmed.ncbi.nlm.nih.gov/23574713/","label":"PubMed (NIH): Hyaluronic acid vaginal gel vs. estriol cream for vaginal dryness (J Sex Med, 2013)"}]}],"scientificCitations":[],"verificationLinks":{"doctor":{"links":[]},"scientific":{"links":[]},"community":{"links":[{"platform":"reddit","url":"https://www.reddit.com/r/AskONLYWomenOver30/comments/1wcgjzy/best_vaginal_moisturizer_youve_tried/","text":"Reddit r/AskONLYWomenOver30: Best vaginal moisturizer you''ve tried?","summary":"A community thread where women over 30 share the vaginal moisturizers they''ve used. Reddit blocks automated access, so ayna couldn''t check which products are mentioned; read the thread directly."},{"platform":"amazon","url":"https://www.amazon.com/dp/B0G4SG1WJY","text":"Amazon: Alubri Vaginal Moisturizer, 72-Hour Hydration, Hormone-Free","summary":"This gel''s Amazon listing (1-month supply), with customer ratings and reviews. Amazon blocks automated access, so no rating is quoted here; read the reviews directly on the page."},{"platform":"website","url":"https://alubri.com/products/vaginal-moisturizing-gel","text":"alubri.com: Vaginal Moisturizing Gel","summary":"Alubri''s own product page, with the brand''s study results and directions."},{"platform":"website","url":"https://alubri.com/pages/faq","text":"alubri.com: FAQ","summary":"Alubri''s answers on first-use sensations, discharge, condoms, and using the gel with vaginal estrogen."}]}},"integrations":[],"badges":[],"isEmergingBrand":false}'::jsonb),
  ('p-alubri-intimate-serum', 'Alubri Intimate Serum', 'Alubri', 'intimate-care', 'physical', 'A lightweight, water-based serum for external intimate skin: the vulva, labia, and vaginal opening. It pairs hyaluronic acid (sodium hyaluronate) with inulin, which Alubri says also supports a healthy skin microbiome, plus aloe, green tea, and chamomile. The brand says it absorbs with no oily residue, feels cooling, and restores the skin''s moisture barrier. Hormone-free and fragrance-free. Sold in a 50 mL pump bottle or a 1.0 fl oz trial size.', '$24.99 (50 mL) · $12.99 (1.0 fl oz trial size)', '/products/alubri/intimate-serum.webp', 'https://alubri.com/products/intimate-serum', '["discomfort","comfort","menopause","hormone-free","external-only"]'::jsonb, '["vaginal-health"]'::jsonb, '["alubri.com","Amazon","Walmart","Target","Grove"]'::jsonb, '{}'::jsonb, '{"fdaStatus":"alubri.com presents it as a hormone-free personal-care serum and does not describe it as an FDA-cleared device or drug.","materials":"50 mL (1.7 fl oz) pump bottle, or 1.0 fl oz trial size. Ingredients: aqua (water), betaine, inulin, sodium lactate, lactic acid, sodium hyaluronate, Aloe barbadensis leaf juice, Camellia sinensis (green tea) leaf extract, Chamomilla recutita (chamomile) flower extract, tocopherol, ethylhexylglycerin, hydroxyethylcellulose, xanthan gum, disodium phosphate, sodium phosphate, citric acid, phenoxyethanol, potassium sorbate, sodium benzoate, sodium hydroxide. Fragrance-free, hormone-free, hypoallergenic.","recalls":"No recalls are mentioned on alubri.com; check current regulator and manufacturer recall notices.","sideEffects":"For external use. Stop and see a doctor if irritation develops. Full warnings are listed below.","opinionAlerts":"Clinical figures (including the 152% hydration increase) come from studies Alubri describes on its own site; the full studies aren''t published there."}'::jsonb, 'Alubri says the serum was developed with Dr. Nicole Kerner, its co-founder and Chief Medical Officer, a board-certified, menopause-certified OB-GYN, and that it is gynecologist- and dermatologist-tested.

The brand reports that in an IRB-approved study run under ISO Good Laboratory Practices, one application raised vulvar hydration by 152% versus baseline, measured 72 hours later. In a separate independent, third-party study of 50 women using the serum for 2 weeks, 94% said their skin felt hydrated, 92% protected and moisturized, 90% soothed and nourished, and 90% said the hydration was long-lasting. These are brand-reported results.', 'There''s a Reddit post about this serum in r/Influenster (linked below). Influenster is a product-testing community whose members often get products free to review, so weigh posts there with that in mind. Reddit blocks automated access, so ayna hasn''t pulled quotes; read it directly. alubri.com itself shows no star rating, only the brand''s own study results (above).', 'Alubri reports a 152% increase in vulvar hydration after one application, and high self-reported hydration after 2 weeks of use, in its own studies. No independent study of this product is cited on alubri.com.', 'brand', 'Sourced only from Alubri''s own site (alubri.com), not independent clinical literature.', 'curated', false, false, null, true, '{"faqUrl":"https://alubri.com/pages/faq","doctorOpinionShort":"Alubri reports one application raised vulvar hydration 152% versus baseline, and in a 2-week study of 50 women, 94% said skin felt hydrated. Brand-reported results.","doctorOpinionCitations":[{"url":"https://alubri.com/products/intimate-serum","label":"alubri.com: where Alubri presents these results"},{"url":"https://alubri.com/pages/science","label":"alubri.com: Science (vulvar hydration)"}],"whoItsFor":["Daily vulvar dryness or discomfort from menopause, perimenopause, hormonal shifts, or medications","Skin recovery after shaving, waxing, or laser hair removal","Postpartum and breastfeeding dryness","Women who prefer non-hormonal intimate care, including those with a history of breast cancer or on anti-estrogen therapies"],"howToUse":{"intro":"Per Alubri''s own directions:","steps":["First use: pump 10 to 15 times to prime the dispenser.","Dispense a small amount onto your fingertips.","Apply over the vulva, labia, and vaginal opening, and massage until absorbed. No need to rinse.","Use daily, or as needed: morning, evening, before or after intimacy, or after grooming."],"sourceUrl":"https://alubri.com/products/intimate-serum","sourceLabel":"alubri.com: Intimate Serum"},"warnings":["For external intimate skin. For internal dryness, Alubri''s internal product is the Vaginal Moisturizing Gel.","Itching or irritation that persists despite a moisturizer can be a sign of infection. See a doctor.","Not tested for compatibility with condoms, per Alubri."],"ingredients":"Sodium hyaluronate (hyaluronic acid), inulin, betaine, lactic acid / sodium lactate, aloe, green tea extract, chamomile extract, vitamin E (tocopherol).","ingredientScienceNote":"These are the key ingredients Alubri highlights on its site, not the full ingredient list. The complete list is under Materials on the Evidence view.","ingredientScience":[{"name":"Inulin","text":"Inulin is a plant fiber best known as a prebiotic that feeds beneficial gut bacteria when eaten; an NIH-indexed review covers how ingested prebiotics may affect distant sites, including skin. ayna found no studies of inulin applied directly to skin, so Alubri''s skin-microbiome claim for this serum hasn''t been tested independently.","citations":[{"url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC5037510/","label":"NIH (PMC): Distant site effects of ingested prebiotics, incl. inulin (Nutrients, 2016)"}]},{"name":"Sodium hyaluronate (hyaluronic acid)","text":"In a double-blind randomized trial of 36 older adults with dry skin, a lotion with low-molecular-weight hyaluronic acid raised skin hydration more than a plain lotion after 4 weeks, with no side effects. The study was on leg skin, not vulvar skin.","citations":[{"url":"https://pubmed.ncbi.nlm.nih.gov/38829483/","label":"PubMed (NIH): Topical hyaluronic acid for dry skin in older adults, randomized trial (Arch Dermatol Res, 2024)"}]}],"scientificCitations":[],"verificationLinks":{"doctor":{"links":[]},"scientific":{"links":[]},"community":{"links":[{"platform":"reddit","url":"https://www.reddit.com/r/Influenster/comments/1pnf635/alubri_intinate_serum/","text":"Reddit r/Influenster: Alubri Intimate Serum","summary":"A post about this serum in the Influenster community, where members often receive products free to review. Reddit blocks automated access, so read the post directly."},{"platform":"website","url":"https://alubri.com/products/intimate-serum","text":"alubri.com: Intimate Serum","summary":"Alubri''s own product page, with the brand''s study results and directions."},{"platform":"website","url":"https://alubri.com/pages/faq","text":"alubri.com: FAQ","summary":"Alubri''s answers on sensitive skin, condoms, and how long a bottle lasts."}]}},"integrations":[],"badges":[],"isEmergingBrand":false}'::jsonb),
  ('p-alubri-calming-cream', 'Alubri Calming Cream', 'Alubri', 'intimate-care', 'physical', 'An over-the-counter anti-itch cream for external intimate skin, with 0.25% hydrocortisone to relieve itching and irritation. The base adds shea butter, hyaluronic acid, lactic acid, oat, aloe, and Alubri''s Activated Oil Complex, which the brand says supports a balanced vulvar microbiome. Alubri positions it as giving the relief of an OTC ointment in a lightweight, non-greasy cream. Hormone-free and fragrance-free.', '$29.99 (50 mL)', '/products/alubri/calming-cream.png', 'https://alubri.com/products/calming-cream', '["discomfort","comfort","menopause","hormone-free","external-only"]'::jsonb, '["vaginal-health"]'::jsonb, '["alubri.com","Amazon","Walmart","Target","Grove"]'::jsonb, '{}'::jsonb, '{"fdaStatus":"An over-the-counter external analgesic (hydrocortisone 0.25%), per alubri.com. External use only.","materials":"50 mL (1.7 fl oz) tube. Active ingredient: hydrocortisone 0.25% (external analgesic). Inactive ingredients: aqua (water), propanediol, cetearyl alcohol, isopropyl palmitate, Butyrospermum parkii (shea) butter, caprylic/capric triglycerides, dimethicone, Cocos nucifera (coconut) oil, glyceryl stearate, hydrolyzed Rosa canina (rosehip) fruit oil, hydrolyzed Cocos nucifera (coconut) oil, sodium hyaluronate, lactic acid, Avena sativa (oat) meal extract, tocopherol, Aloe barbadensis leaf juice, Lactobacillus ferment lysate, hydrogenated lecithin, cetearyl glucoside, sclerotium gum, dimethicone crosspolymer, xanthan gum, ethylhexylglycerin, butylene glycol, phenoxyethanol, isododecane.","recalls":"No recalls are mentioned on alubri.com; check current regulator and manufacturer recall notices.","sideEffects":"For external use only. Alubri says to check with a healthcare professional first if you have specific sensitivities or use prescription topical products. Full warnings are listed below.","opinionAlerts":"This is an OTC drug; alubri.com doesn''t reproduce the full Drug Facts label, so read the warnings on the package before use. Clinical figures are brand-reported."}'::jsonb, 'Alubri says the cream was developed with Dr. Nicole Kerner, its co-founder and Chief Medical Officer, a board-certified, menopause-certified OB-GYN. The brand says it chose 0.25% hydrocortisone as a strength that gives fast relief while staying gentle on sensitive skin.

In an independent, third-party study of 53 menopausal women who used the cream for 24 hours, Alubri reports that 94% said their skin felt soothed after one application, 94% protected, 96% nourished and conditioned, and 98% said it was easy to use. These are brand-reported results.

Alubri''s professional FAQ says the cream isn''t intended to treat skin conditions, but may be used alongside doctor-prescribed treatment for conditions such as lichen sclerosus to help soothe and support comfort.', 'alubri.com doesn''t show a star rating or review count for this cream. The only customer feedback on the site is the brand''s own study results: 92% said it isn''t greasy and 100% said it was easy to use.', 'Hydrocortisone is the active ingredient for itch relief. Alubri''s own study of 53 women reports that 94% felt soothed after one application. No independent study of this product is cited on alubri.com.', 'brand', 'Sourced only from Alubri''s own site (alubri.com), not independent clinical literature.', 'curated', false, false, null, true, '{"faqUrl":"https://alubri.com/pages/faq","doctorOpinionShort":"An OTC 0.25% hydrocortisone cream. In Alubri''s study of 53 menopausal women, 94% said skin felt soothed after one application. Brand-reported results.","doctorOpinionCitations":[{"url":"https://alubri.com/products/calming-cream","label":"alubri.com: where Alubri presents these results"},{"url":"https://alubri.com/pages/faq","label":"alubri.com: FAQ (why 0.25% hydrocortisone)"}],"whoItsFor":["Temporary relief of external feminine itching","Vulvar irritation from menopause, perimenopause, or hormonal changes","Itching and sensitivity from shaving, waxing, or friction","Itching and sensitivity after exercise or sex"],"howToUse":{"intro":"Per Alubri''s own directions:","steps":["Apply a pea-size amount to the external vulvar area with clean fingers.","Add more as needed to cover the affected area in a thin layer.","Use up to 3 to 4 times a day as needed, or as directed by a healthcare provider.","Tip: use after intimacy, exercise, or friction. If certain activities tend to irritate your skin, Alubri suggests applying it beforehand."],"sourceUrl":"https://alubri.com/products/calming-cream","sourceLabel":"alubri.com: Calming Cream"},"warnings":["External use only.","Contains hydrocortisone, a topical steroid. Read the Drug Facts label on the package before use.","Itching or irritation that persists can be a sign of infection. See a doctor.","Not tested for compatibility with condoms, per Alubri."],"ingredients":"Hydrocortisone 0.25% (active). Inactive highlights: shea butter, sodium hyaluronate (hyaluronic acid), lactic acid, oat extract, aloe, Activated Oil Complex (hydrolyzed coconut and rosehip oils), vitamin E (tocopherol).","ingredientScienceNote":"These are the key ingredients Alubri highlights on its site, not the full ingredient list. The complete list is under Materials on the Evidence view.","ingredientScience":[{"name":"Coconut and rosehip oils (Activated Oil Complex)","text":"Applied to dry skin twice a day for 2 weeks, virgin coconut oil improved hydration as well as mineral oil in a randomized, double-blind trial. An NIH-indexed review notes rosehip oil is rich in linoleic acid and antioxidants that may help calm skin inflammation. These studies used ordinary oils on skin, not Alubri''s \"pre-activated\" blend, so the brand''s microbiome claims aren''t tested by them.","citations":[{"url":"https://pubmed.ncbi.nlm.nih.gov/15724344/","label":"PubMed (NIH): Virgin coconut oil vs. mineral oil for dry skin, randomized trial (Dermatitis, 2004)"},{"url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC5796020/","label":"NIH (PMC): Anti-inflammatory and skin barrier effects of plant oils, incl. rosehip (Int J Mol Sci, 2017)"}]},{"name":"Hydrocortisone 0.25%","text":"NIH''s MedlinePlus describes topical hydrocortisone as a corticosteroid used to treat redness, swelling, itching, and discomfort of skin conditions. It works by activating natural substances in the skin that reduce swelling, redness, and itching.","citations":[{"url":"https://medlineplus.gov/druginfo/meds/a682793.html","label":"NIH MedlinePlus: Hydrocortisone Topical"}]},{"name":"Shea butter","text":"In a study of 34 children with eczema, a cream containing shea butter extract was well accepted and performed comparably to a ceramide-based product. Shea butter''s triterpenes, tocopherols, and sterols have shown anti-inflammatory activity in lab studies.","citations":[{"url":"https://pubmed.ncbi.nlm.nih.gov/26314567/","label":"PubMed (NIH): Shea butter extract cream vs. ceramide product for eczema (Hong Kong Med J, 2015)"}]}],"scientificCitations":[],"verificationLinks":{"doctor":{"links":[]},"scientific":{"links":[]},"community":{"links":[{"platform":"website","url":"https://alubri.com/products/calming-cream","text":"alubri.com: Calming Cream","summary":"Alubri''s own product page, with the brand''s study results and directions."},{"platform":"website","url":"https://alubri.com/pages/faq","text":"alubri.com: FAQ","summary":"Alubri''s answers on the hydrocortisone strength and use alongside prescribed treatment."}]}},"integrations":[],"badges":[],"isEmergingBrand":false}'::jsonb),
  ('p-alubri-vulva-balm', 'Alubri Vulva Balm', 'Alubri', 'intimate-care', 'physical', 'A non-greasy daily moisturizer for the vulva that Alubri says hydrates, soothes, protects against dryness, and calms sensitive skin. It combines hyaluronic acid (sodium hyaluronate), a peptide, and Alubri''s Activated Oil Complex with oat, green tea, dragon fruit, and Tasmanian pepperberry extracts. The brand describes a rich but lightweight balm that absorbs quickly to a soft, powdery finish. Hormone-free, fragrance-free, and hypoallergenic.', '$24.99 (50 g)', '/products/alubri/vulva-balm.png', 'https://alubri.com/products/vulva-balm', '["discomfort","comfort","menopause","hormone-free","external-only"]'::jsonb, '["vaginal-health"]'::jsonb, '["alubri.com","Amazon","Walmart","Target","Grove"]'::jsonb, '{}'::jsonb, '{"fdaStatus":"alubri.com presents it as a hormone-free personal-care moisturizer and does not describe it as an FDA-cleared device or drug.","materials":"50 g (1.7 oz) jar. Ingredients: aqua (water), dimethicone, isododecane, caprylic/capric triglyceride, ozokerite, propanediol, sorbitan oleate, dimethicone crosspolymer, ceresin, hydrolyzed Rosa canina (rosehip) fruit oil, hydrolyzed Cocos nucifera (coconut) oil, sodium hyaluronate, palmitoyl hexapeptide-52, Hylocereus undatus (dragon fruit) fruit extract, Tasmannia lanceolata (Tasmanian pepperberry) fruit extract, Avena sativa (oat) kernel extract, Camellia sinensis (green tea) leaf extract, Passiflora incarnata flower extract, tocopherol, alpha-glucan oligosaccharide, tocopheryl acetate, Lactobacillus ferment lysate, biosaccharide gum-4, adenosine, ethylhexylglycerin, phenoxyethanol, sodium chloride, benzyl alcohol, potassium sorbate, benzoic acid.","recalls":"No recalls are mentioned on alubri.com; check current regulator and manufacturer recall notices.","sideEffects":"For external use only. Alubri suggests testing a small amount on external skin first. Full warnings are listed below.","opinionAlerts":"Clinical figures (including the vulvar pH result) come from a study Alubri describes on its own site; the full study isn''t published there."}'::jsonb, 'Alubri says the balm was developed with Dr. Nicole Kerner, its co-founder and Chief Medical Officer, a board-certified, menopause-certified OB-GYN, and that it is gynecologist- and dermatologist-tested.

In an independent, third-party study of 50 women who used the balm daily for two weeks, Alubri reports that vulvar pH in menopausal women dropped significantly (from 6.3 to 6.0) at both 24 hours and two weeks. The brand notes that postmenopausal vaginal pH is typically well above the 3.8 to 4.5 range of reproductive-age women. Participants also reported that skin felt more hydrated (90%) and more conditioned (92%). These are brand-reported results.

Alubri''s professional FAQ says the balm isn''t intended to treat skin conditions, but may be used alongside doctor-prescribed treatment for conditions such as lichen sclerosus.', 'alubri.com doesn''t show a star rating or review count for this balm. The only customer feedback on the site is the brand''s own study results: 92% said it isn''t greasy and 100% said it was easy to use.', 'Alubri reports a significant drop in vulvar pH (6.3 to 6.0) after 24 hours and two weeks, plus high self-reported hydration, in its own study of 50 women. No independent study of this product is cited on alubri.com.', 'brand', 'Sourced only from Alubri''s own site (alubri.com), not independent clinical literature.', 'curated', false, false, null, true, '{"faqUrl":"https://alubri.com/pages/faq","doctorOpinionShort":"In Alubri''s 2-week study of 50 women, vulvar pH fell from 6.3 to 6.0 and 90% said skin felt more hydrated. Developed by a menopause-certified OB-GYN. Brand-reported results.","doctorOpinionCitations":[{"url":"https://alubri.com/products/vulva-balm","label":"alubri.com: where Alubri presents these results"},{"url":"https://alubri.com/pages/science","label":"alubri.com: Science (pH results)"}],"whoItsFor":["Vulvar dryness from menopause, perimenopause, or hormonal changes","Women who want daily microbiome and pH support for intimate skin","Anyone who needs hormone-free vulvar care","A daily protective layer under clothing, or before workouts, beach days, or tight clothing"],"howToUse":{"intro":"Per Alubri''s own directions:","steps":["Scoop a small amount onto your fingertips.","Apply over the vulva, labia, and surrounding external intimate skin.","Use daily, morning or evening, and reapply whenever skin feels dry.","Tip: apply after a shower, while skin is clean and slightly damp, to help lock in moisture."],"sourceUrl":"https://alubri.com/products/vulva-balm","sourceLabel":"alubri.com: Vulva Balm"},"warnings":["For external use only.","Itching or irritation that persists despite a moisturizer can be a sign of infection. See a doctor.","Not tested for compatibility with condoms, per Alubri."],"ingredients":"Sodium hyaluronate (hyaluronic acid), palmitoyl hexapeptide-52 (peptide), Activated Oil Complex (hydrolyzed coconut and rosehip oils), dragon fruit extract, Tasmanian pepperberry extract, oat kernel extract, green tea extract, vitamin E (tocopherol).","ingredientScienceNote":"These are the key ingredients Alubri highlights on its site, not the full ingredient list. The complete list is under Materials on the Evidence view.","ingredientScience":[{"name":"Coconut and rosehip oils (Activated Oil Complex)","text":"Applied to dry skin twice a day for 2 weeks, virgin coconut oil improved hydration as well as mineral oil in a randomized, double-blind trial. An NIH-indexed review notes rosehip oil is rich in linoleic acid and antioxidants that may help calm skin inflammation. These studies used ordinary oils on skin, not Alubri''s \"pre-activated\" blend, so the brand''s microbiome claims aren''t tested by them.","citations":[{"url":"https://pubmed.ncbi.nlm.nih.gov/15724344/","label":"PubMed (NIH): Virgin coconut oil vs. mineral oil for dry skin, randomized trial (Dermatitis, 2004)"},{"url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC5796020/","label":"NIH (PMC): Anti-inflammatory and skin barrier effects of plant oils, incl. rosehip (Int J Mol Sci, 2017)"}]},{"name":"Allantoin","text":"Alubri lists allantoin as a key ingredient for softening and soothing skin, but it doesn''t appear in the balm''s published ingredient list on alubri.com. In an NIH-indexed study in rats, a 5% allantoin lotion sped wound healing by calming inflammation and supporting new tissue growth; ayna found no human studies of allantoin for vulvar skin.","citations":[{"url":"https://pubmed.ncbi.nlm.nih.gov/20877959/","label":"PubMed (NIH): Wound healing profile of topical allantoin, rat study (Acta Cir Bras, 2010)"}]},{"name":"Sodium hyaluronate (hyaluronic acid)","text":"In a double-blind randomized trial of 36 older adults with dry skin, a lotion with low-molecular-weight hyaluronic acid raised skin hydration more than a plain lotion after 4 weeks, with no side effects. The study was on leg skin, not vulvar skin.","citations":[{"url":"https://pubmed.ncbi.nlm.nih.gov/38829483/","label":"PubMed (NIH): Topical hyaluronic acid for dry skin in older adults, randomized trial (Arch Dermatol Res, 2024)"}]}],"scientificCitations":[],"verificationLinks":{"doctor":{"links":[]},"scientific":{"links":[]},"community":{"links":[{"platform":"website","url":"https://alubri.com/products/vulva-balm","text":"alubri.com: Vulva Balm","summary":"Alubri''s own product page, with the brand''s study results and directions."},{"platform":"website","url":"https://alubri.com/pages/faq","text":"alubri.com: FAQ","summary":"Alubri''s answers on daily use, use with vaginal estrogen, and how long a jar lasts."}]}},"integrations":[],"badges":[],"isEmergingBrand":false}'::jsonb),
  ('p-alubri-vaginal-wellness-kit', 'Alubri Vaginal Wellness Kit', 'Alubri', 'intimate-care', 'physical', 'A 2-week trial kit of Alubri''s two core moisturizers in trial sizes: the Vaginal Moisturizing Gel (30 mL, with single-use applicators) for internal hydration and microbiome balance, and the Intimate Serum (30 mL) for external vulvar hydration. Alubri pitches it as an easy introduction to the brand.', '$19.99 (2-week trial)', '/products/alubri/vaginal-wellness-kit.webp', 'https://alubri.com/products/vaginal-wellness-kit-bag-version', '["discomfort","comfort","menopause","hormone-free","travel-friendly"]'::jsonb, '["vaginal-health"]'::jsonb, '["alubri.com","Amazon","Walmart","Target","Grove"]'::jsonb, '{}'::jsonb, '{"fdaStatus":"alubri.com presents both products as hormone-free personal-care moisturizers and does not describe either as an FDA-cleared device or drug.","materials":"1 × 30 mL (1.0 fl oz) Vaginal Moisturizing Gel with single-use applicators, and 1 × 30 mL (1.0 fl oz) Intimate Serum. Full ingredient lists are on the Alubri Vaginal Moisturizing Gel and Alubri Intimate Serum entries. Hormone-free and fragrance-free.","recalls":"No recalls are mentioned on alubri.com; check current regulator and manufacturer recall notices.","sideEffects":"Alubri says some women feel mild warming or brief stinging on first use of the gel, which usually fades. If discomfort persists, stop and see a doctor. Full warnings are listed below.","opinionAlerts":"Clinical figures for each product are brand-reported (see the full-size Gel and Serum entries)."}'::jsonb, 'The same two formulas as Alubri''s full-size Vaginal Moisturizing Gel and Intimate Serum, developed with Dr. Nicole Kerner, Alubri''s co-founder and Chief Medical Officer, a board-certified, menopause-certified OB-GYN.

Alubri reports that in its study of 51 women using the gel twice a week for a month, 94% said their vagina felt moisturized and hydrated, 92% soothed, and 88% said the gel stayed put. In its 2-week study of 50 women using the serum, 94% said their skin felt hydrated and 90% said the hydration was long-lasting. These are brand-reported results.', 'alubri.com doesn''t show a star rating or review count for this kit. The only customer feedback on the site is the brand''s own study results for each product (above).', 'Each product''s results come from Alubri''s own studies (see the full-size Gel and Serum entries). No independent study of either product is cited on alubri.com.', 'brand', 'Sourced only from Alubri''s own site (alubri.com), not independent clinical literature.', 'curated', true, false, null, true, '{"faqUrl":"https://alubri.com/pages/faq","doctorOpinionShort":"A 2-week trial of Alubri''s internal gel and external serum. In the brand''s studies, 94% said the gel left them feeling moisturized and 94% said the serum left skin hydrated. Brand-reported results.","doctorOpinionCitations":[{"url":"https://alubri.com/products/vaginal-wellness-kit-bag-version","label":"alubri.com: Vaginal Wellness Kit"}],"whoItsFor":["Women with dryness or discomfort tied to perimenopause, menopause, or hormonal shifts","Painful intimacy linked to dryness","Anyone who wants to try Alubri''s internal and external moisturizers before buying full sizes"],"howToUse":{"intro":"Per Alubri''s own directions for each product:","steps":["Gel (internal): attach a single-use applicator, squeeze to fill to 3 grams, insert, and push to release. Throw the applicator away. Use twice a week or as needed, ideally before bed, and lie flat for 10 minutes afterward.","Serum (external): apply over the vulva, clitoris, labia, and vaginal opening for daily hydration or intimate massage. Can also be used after grooming."],"sourceUrl":"https://alubri.com/products/vaginal-wellness-kit-bag-version","sourceLabel":"alubri.com: Vaginal Wellness Kit"},"warnings":["A mild warming or blushing feeling on first use of the gel is normal per Alubri. If discomfort persists, stop and see a doctor.","Itching or irritation that persists despite a moisturizer can be a sign of infection. See a doctor.","Not tested for compatibility with condoms, per Alubri."],"ingredients":"Gel: sodium hyaluronate, lactic acid, Activated Oil Complex (hydrolyzed coconut and rosehip oils), dragon fruit extract, aloe. Serum: sodium hyaluronate, inulin, betaine, lactic acid, aloe, green tea, chamomile.","ingredientScienceNote":"These are the key ingredients Alubri highlights on its site, not the full ingredient list. The complete list is under Materials on the Evidence view.","ingredientScience":[{"name":"Coconut and rosehip oils (Activated Oil Complex)","text":"Applied to dry skin twice a day for 2 weeks, virgin coconut oil improved hydration as well as mineral oil in a randomized, double-blind trial. An NIH-indexed review notes rosehip oil is rich in linoleic acid and antioxidants that may help calm skin inflammation. These studies used ordinary oils on skin, not Alubri''s \"pre-activated\" blend, so the brand''s microbiome claims aren''t tested by them.","citations":[{"url":"https://pubmed.ncbi.nlm.nih.gov/15724344/","label":"PubMed (NIH): Virgin coconut oil vs. mineral oil for dry skin, randomized trial (Dermatitis, 2004)"},{"url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC5796020/","label":"NIH (PMC): Anti-inflammatory and skin barrier effects of plant oils, incl. rosehip (Int J Mol Sci, 2017)"}]},{"name":"Inulin","text":"Inulin is a plant fiber best known as a prebiotic that feeds beneficial gut bacteria when eaten; an NIH-indexed review covers how ingested prebiotics may affect distant sites, including skin. ayna found no studies of inulin applied directly to skin, so Alubri''s skin-microbiome claim for this serum hasn''t been tested independently.","citations":[{"url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC5037510/","label":"NIH (PMC): Distant site effects of ingested prebiotics, incl. inulin (Nutrients, 2016)"}]},{"name":"Aloe","text":"NIH''s National Center for Complementary and Integrative Health says aloe gel on the skin is generally well tolerated, and small studies suggest it may speed burn healing and help some skin conditions. Evidence for other uses, like eczema, is too limited to say. Burning, itching, or rash have occasionally been reported.","citations":[{"url":"https://www.nccih.nih.gov/health/aloe-vera","label":"NIH NCCIH: Aloe Vera"}]}],"scientificCitations":[],"verificationLinks":{"doctor":{"links":[]},"scientific":{"links":[]},"community":{"links":[{"platform":"website","url":"https://alubri.com/products/vaginal-wellness-kit-bag-version","text":"alubri.com: Vaginal Wellness Kit","summary":"Alubri''s own product page, with kit contents, directions, and the brand''s study results."}]}},"integrations":[],"badges":[],"isEmergingBrand":false}'::jsonb),
  ('p-alubri-rejuvenate-restore-kit', 'Alubri Rejuvenate & Restore Kit', 'Alubri', 'intimate-care', 'physical', 'A trial-size pair of Alubri''s two external products for comfort before and after intimacy: the Intimate Serum (28 mL) for daily water-based hydration, and the Calming Cream (30 mL), an OTC 0.25% hydrocortisone cream for itching and irritation. Both are hormone-free and fragrance-free.', '$19.99 (trial sizes)', '/products/alubri/rejuvenate-restore-kit.png', 'https://alubri.com/products/rejuvenate-restore-kit', '["discomfort","comfort","menopause","hormone-free","external-only","travel-friendly"]'::jsonb, '["vaginal-health"]'::jsonb, '["alubri.com"]'::jsonb, '{}'::jsonb, '{"fdaStatus":"The Calming Cream is an over-the-counter external analgesic (hydrocortisone 0.25%), per alubri.com. The Intimate Serum is presented as a personal-care serum and is not described as an FDA-cleared device or drug.","materials":"1 × 28 mL (0.9 fl oz) Intimate Serum and 1 × 30 mL (1.0 fl oz) Calming Cream. Full ingredient lists are on the Alubri Intimate Serum and Alubri Calming Cream entries. Hormone-free and fragrance-free.","recalls":"No recalls are mentioned on alubri.com; check current regulator and manufacturer recall notices.","sideEffects":"Both products are for external use only. The cream contains hydrocortisone; read the Drug Facts label on the package before use. Full warnings are listed below.","opinionAlerts":"Clinical figures for each product are brand-reported (see the full-size Serum and Calming Cream entries)."}'::jsonb, 'The same two formulas as Alubri''s full-size Intimate Serum and Calming Cream, developed with Dr. Nicole Kerner, Alubri''s co-founder and Chief Medical Officer, a board-certified, menopause-certified OB-GYN.

Alubri reports that in its 2-week study of 50 women using the serum, 94% said their skin felt hydrated and 92% protected and moisturized. In its study of 53 women using the cream for 24 hours, 94% said their skin felt soothed and 96% nourished and conditioned. These are brand-reported results.', 'alubri.com doesn''t show a star rating or review count for this kit. The only customer feedback on the site is the brand''s own study results for each product (above).', 'Each product''s results come from Alubri''s own studies (see the full-size Serum and Calming Cream entries). No independent study of either product is cited on alubri.com.', 'brand', 'Sourced only from Alubri''s own site (alubri.com), not independent clinical literature.', 'curated', false, false, null, true, '{"faqUrl":"https://alubri.com/pages/faq","doctorOpinionShort":"Trial sizes of Alubri''s external serum and 0.25% hydrocortisone cream. In the brand''s studies, 94% said the serum left skin hydrated and 94% said the cream soothed. Brand-reported results.","doctorOpinionCitations":[{"url":"https://alubri.com/products/rejuvenate-restore-kit","label":"alubri.com: Rejuvenate & Restore Kit"}],"whoItsFor":["Tender, sensitive, dry, or itchy external intimate skin","Relief from discomfort after intimacy","Women whose skin needs are changing through menopause"],"howToUse":{"intro":"Per Alubri''s own directions for each product:","steps":["Serum: with clean fingers, apply over the vulva (clitoris, labia, and vaginal opening) for hydration or intimate massage.","Cream: apply a pea-size amount to the external vulvar area with clean fingers, adding more as needed for a thin layer. Use up to 3 to 4 times a day as needed.","Tip: use the cream after intimacy, exercise, or anytime friction leaves skin tender."],"sourceUrl":"https://alubri.com/products/rejuvenate-restore-kit","sourceLabel":"alubri.com: Rejuvenate & Restore Kit"},"warnings":["External use only.","The Calming Cream contains hydrocortisone, a topical steroid. Read the Drug Facts label on the package before use.","Itching or irritation that persists can be a sign of infection. See a doctor.","Not tested for compatibility with condoms, per Alubri."],"ingredients":"Serum: sodium hyaluronate, inulin, betaine, lactic acid, aloe, green tea, chamomile. Cream: hydrocortisone 0.25% (active), shea butter, sodium hyaluronate, lactic acid, oat extract, aloe, Activated Oil Complex (hydrolyzed coconut and rosehip oils).","ingredientScienceNote":"These are the key ingredients Alubri highlights on its site, not the full ingredient list. The complete list is under Materials on the Evidence view.","ingredientScience":[{"name":"Hydrocortisone 0.25%","text":"NIH''s MedlinePlus describes topical hydrocortisone as a corticosteroid used to treat redness, swelling, itching, and discomfort of skin conditions. It works by activating natural substances in the skin that reduce swelling, redness, and itching.","citations":[{"url":"https://medlineplus.gov/druginfo/meds/a682793.html","label":"NIH MedlinePlus: Hydrocortisone Topical"}]},{"name":"Aloe","text":"NIH''s National Center for Complementary and Integrative Health says aloe gel on the skin is generally well tolerated, and small studies suggest it may speed burn healing and help some skin conditions. Evidence for other uses, like eczema, is too limited to say. Burning, itching, or rash have occasionally been reported.","citations":[{"url":"https://www.nccih.nih.gov/health/aloe-vera","label":"NIH NCCIH: Aloe Vera"}]},{"name":"Coconut and rosehip oils (Activated Oil Complex)","text":"Applied to dry skin twice a day for 2 weeks, virgin coconut oil improved hydration as well as mineral oil in a randomized, double-blind trial. An NIH-indexed review notes rosehip oil is rich in linoleic acid and antioxidants that may help calm skin inflammation. These studies used ordinary oils on skin, not Alubri''s \"pre-activated\" blend, so the brand''s microbiome claims aren''t tested by them.","citations":[{"url":"https://pubmed.ncbi.nlm.nih.gov/15724344/","label":"PubMed (NIH): Virgin coconut oil vs. mineral oil for dry skin, randomized trial (Dermatitis, 2004)"},{"url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC5796020/","label":"NIH (PMC): Anti-inflammatory and skin barrier effects of plant oils, incl. rosehip (Int J Mol Sci, 2017)"}]}],"scientificCitations":[],"verificationLinks":{"doctor":{"links":[]},"scientific":{"links":[]},"community":{"links":[{"platform":"website","url":"https://alubri.com/products/rejuvenate-restore-kit","text":"alubri.com: Rejuvenate & Restore Kit","summary":"Alubri''s own product page, with kit contents, directions, and the brand''s study results."}]}},"integrations":[],"badges":[],"isEmergingBrand":false}'::jsonb)
